// import AOS from "aos";
import "aos/dist/aos.css";
import { FaBullhorn, FaGlobe, FaPaintBrush, FaPenNib, FaChartLine, FaWhatsapp } from "react-icons/fa";
import AppContext from "../../../Context";
import { useContext } from "react";

function Advertising() {
    //-----------------------STATE VIEWS-----------------------//
    const { language } = useContext(AppContext);
    const advertisingServices = [
        {
            title:
                language === "id"
                    ? "Iklan Website"
                    : "Website Advertising",
            description:
                language === "id"
                    ? "Pengembangan dan pengelolaan website promosi yang efektif dan berorientasi pada konversi."
                    : "Development and management of effective, conversion-oriented promotional websites.",
            icon: FaGlobe,
        },
        {
            title:
                language === "id"
                    ? "Desain"
                    : "Design",
            description:
                language === "id"
                    ? "Layanan desain visual profesional untuk kebutuhan branding dan materi promosi."
                    : "Professional visual design services for branding and promotional materials.",
            icon: FaPaintBrush,
        },
        {
            title:
                language === "id"
                    ? "Penulisan Konten"
                    : "Copywriting",
            description:
                language === "id"
                    ? "Penulisan konten persuasif untuk memperkuat pesan dan identitas brand Anda."
                    : "Persuasive content writing to strengthen your brand message and identity.",
            icon: FaPenNib,
        },
        {
            title:
                language === "id"
                    ? "Pemasaran Digital"
                    : "Digital Marketing",
            description:
                language === "id"
                    ? "Strategi pemasaran digital terintegrasi untuk memperluas jangkauan dan meningkatkan performa bisnis."
                    : "Integrated digital marketing strategies to expand reach and enhance business performance.",
            icon: FaChartLine,
        },
    ];
    const WA_NUMBER = "6281213094426";
    //-----------------------STATE VIEWS-----------------------//

    //------------------------FUNCTIONS------------------------// 
    const getWaLink = (serviceName: string) => {
        const rawMessage =
            language === "id"
                ? `Halo Regarde,\nSaya ingin bertanya lebih lanjut mengenai layanan ${serviceName}.\nMohon informasinya. Terima kasih.`
                : `Hello Regarde,\nI would like to inquire further about the ${serviceName} service.\nPlease provide the details. Thank you.`;

        return `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(rawMessage)}`;
    };
    //------------------------FUNCTIONS------------------------// 

    return (
        <div className="pt-24">
            {/* ADVERTISING DETAIL */}
            <section className="pb-24 bg-white" data-aos="zoom-in">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-primary-blue-100 flex items-center justify-center">
                            <FaBullhorn className="text-primary-blue-700 text-4xl" />
                        </div>
                    </div>
                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-primary-black-500 mb-4">
                        {language === "id" ? "Periklanan" : "Advertising"}
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-primary-black-500 max-w-2xl mx-auto mb-14">
                        {language === "id"
                            ? "Layanan periklanan terintegrasi untuk membantu brand membangun identitas, meningkatkan visibilitas, dan menjangkau target audiens secara efektif."
                            : "Integrated advertising services to help brands build identity, increase visibility, and effectively reach their target audience."}
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {advertisingServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-primary-blue-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-primary-black-500">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-primary-black-500 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className=" mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition "
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>

                            );
                        })}
                    </div>

                </div>
            </section>
        </div>
    );
}

export default Advertising;
